def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The vertical guides are the isolated colored cells below the horizontal bars.
    last_bar = max(r for r, row in enumerate(grid) if sum(v != 0 for v in row) >= 3)
    guides = {c for r in range(last_bar + 1, h) for c, v in enumerate(grid[r]) if v}
    crossings = {}
    for c in guides:
        hits = []
        for r in range(last_bar + 1):
            color = grid[r][c]
            if color == 0:
                left = c > 0 and grid[r][c-1] != 0
                right = c+1 < w and grid[r][c+1] != 0
                if left and right and grid[r][c-1] == grid[r][c+1]:
                    color = grid[r][c-1]
            if color:
                # Only horizontal-bar crossings define the projected vertical path.
                if (c > 0 and grid[r][c-1] == color) or (c+1 < w and grid[r][c+1] == color):
                    hits.append((r, color))
        if hits:
            crossings[c] = hits
    for c, hits in crossings.items():
        start = 0
        for r, color in hits:
            for rr in range(start, r+1):
                out[rr][c] = color
            start = r + 1
    return out
